/**
 * hevi v1.5 默认禁用集合(advisor R5 §4 暂定)。
 *
 * v2.0+ 启用时,从此集合移除该 feature 即可。
 *
 * **注意**: 这是模块级 mutable Set,适用于客户端单进程。
 * 多租户场景应通过 Provider context 注入,不依赖此全局。
 */
declare const HEVI_V1_5_DISABLED: Set<HeviFeature>;
/**
 * 检查某功能在 hevi v1.5 是否启用。
 *
 * @example
 *   import { OBlockedCard, HeviFeature, isHeviFeatureEnabled } from '@helios/blocks';
 *
 *   if (!isHeviFeatureEnabled(HeviFeature.MultiLangTTS)) {
 *     return (
 *       <OBlockedCard
 *         title="多语言 TTS"
 *         reason="v1.5 仅支持中文 Edge TTS"
 *         estimatedAvailability="v2.0(预计 2026-Q4 起评估)"
 *         alternative="可手动用 Google Translate + 单独 TTS service 后期配音"
 *       />
 *     );
 *   }
 */
declare function isHeviFeatureEnabled(feature: HeviFeature): boolean;

/**
 * Tide v2 / A 股市场专属字段防呆 helper。
 *
 * 来源:Tide 经理人 R1 (2026-05-22) §6。
 * 每个 helper 对应一个真实历史 bug 或单位歧义,**只用 helper,不直接算术**。
 *
 * 注意:这些 helper 是 Tide 项目专属(A 股语义),不是跨项目通用。
 *       命名前缀 `aShares*` 明确边界。
 */
/**
 * 格式化涨跌幅(单位:百分比,后端已乘 100)。
 *
 * Sprint 1 真实 bug:DB 列名 `pct_change`,SQL 写 `pct_chg` 报 500。
 * 防呆方式:用本函数后强制传 number,字段名错会先 TS 报。
 *
 * @example
 *   aSharesFormatPctChange(2.35)   // "+2.35%"
 *   aSharesFormatPctChange(-1.5)   // "-1.50%"
 *   aSharesFormatPctChange(0)      // "0.00%"
 */
declare function aSharesFormatPctChange(value: number): string;
/**
 * 格式化市值(单位:亿元)。
 *
 * v1 真实 bug 来源:`market_cap_yi` 单位是亿元,不是元。
 * 直接 toLocaleString 会显示 `12,345` (亿) 看起来像元,误导用户。
 *
 * @example
 *   aSharesFormatMarketCapYi(125)      // "125 亿"
 *   aSharesFormatMarketCapYi(12500)    // "1.25 万亿"
 *   aSharesFormatMarketCapYi(0.85)     // "0.85 亿"
 */
declare function aSharesFormatMarketCapYi(yi: number): string;
/**
 * 格式化连板数。`consecutive_days` 是 **不含今天** 的连板数,
 * 显示时要 +1(2 = 已经 2 个涨停板,显示"2 连板"= 总共今天是第 2 个)。
 *
 * **真语义陷阱**:后端 `consecutive_days=2` 意思是"连 2 个涨停板"(含今天)。
 *                 不是"已经连 2 天涨停,今天是第 3 天"。
 *
 * @example
 *   aSharesFormatConsecutive(1)  // "首板"
 *   aSharesFormatConsecutive(2)  // "2 连板"
 *   aSharesFormatConsecutive(7)  // "7 连板"
 */
declare function aSharesFormatConsecutive(days: number): string;
/**
 * 格式化封单强度。`seal_strength = 封单金额 / 总成交金额`,可能 > 1。
 *
 * @example
 *   aSharesFormatSealStrength(0.5)   // "0.50"(弱封)
 *   aSharesFormatSealStrength(2.3)   // "2.30"(强封)
 *   aSharesFormatSealStrength(10)    // "10.0"(死封)
 */
declare function aSharesFormatSealStrength(strength: number): string;
/**
 * A 股每日涨跌幅限制。
 * - ST 股:5%
 * - 主板 / 中小板:10%
 * - 创业板(300xxx) / 科创板(688xxx) / 北交所(8xxxxx):20%
 */
declare enum ADailyLimitPct {
    ST = 0.05,
    Main = 0.1,
    Growth = 0.2
}
/**
 * 根据股票代码推断涨跌幅限制(粗略推断,具体以后端为准)。
 */
declare function aSharesInferDailyLimit(code: string, isSt?: boolean): ADailyLimitPct;
/**
 * 解析财报报告期字符串。
 * @example
 *   aSharesParseReportPeriod("2025Q4")  // { year: 2025, quarter: 4 }
 *   aSharesParseReportPeriod("2025Q1")  // { year: 2025, quarter: 1 }
 *   aSharesParseReportPeriod("bad")     // null
 */
declare function aSharesParseReportPeriod(s: string): {
    year: number;
    quarter: 1 | 2 | 3 | 4;
} | null;
/**
 * 格式化 LLM 单次生成成本(单位:人民币元)。
 *
 * Tide v2 LLM cost 通常很小(¥0.001 / 次量级),用 toFixed(2) 会丢精度。
 *
 * @example
 *   aSharesFormatLlmCost(0.001)   // "¥0.001"
 *   aSharesFormatLlmCost(0.12)    // "¥0.12"
 *   aSharesFormatLlmCost(2.5)     // "¥2.50"
 */
declare function aSharesFormatLlmCost(cny: number): string;
/**
 * 日期字段的语义类型(防止字段混用)。
 *
 * 实际使用时把它当 nominal type:
 * ```typescript
 * interface Stock {
 *   trade_date: ADateString<'trade'>;       // 交易日(节假日跳过)
 *   report_period_end: ADateString<'fiscal'>; // 财报截止
 *   publish_date: ADateString<'publish'>;   // 公告发布日
 * }
 * ```
 *
 * 实际是 string,但 TS 编译时区分类型避免误用。
 */
type ADateString<T extends 'trade' | 'fiscal' | 'publish'> = string & {
    readonly __dateKind: T;
};

